rors": {"7/2": "qf_halbes_p_nicht_quadriert", "3,5": "qf_halbes_p_nicht_quadriert", "3.5": "qf_halbes_p_nicht_quadriert", "-49/4": "qf_q_vorzeichen", "−49/4": "qf_q_vorzeichen", "-12,25": "qf_q_vorzeichen", "−12,25": "qf_q_vorzeichen", "-12.25": "qf_q_vorzeichen", "−12.25": "qf_q_vorzeichen"}}, "parts": null, "figur": null, "optionen": null, "solution": "Genau eine Lösung heißt: (p/2)² − q = 0.\n(7/2)² − q = 0\nq = (7/2)²\nq = 49/4", "hints": [{"level": 1, "text": "Wann hat eine quadratische Gleichung genau eine Lösung?", "status": "entwurf"}, {"level": 2, "text": "Der Ausdruck unter der Wurzel muss 0 sein: (p/2)² − q = 0.", "status": "entwurf"}, {"level": 3, "text": "Setz p = 7 ein und stell nach q um.", "status": "entwurf"}]}, {"suffix": "generalprobe-s5-434abc31e4", "input_type": "NUMERIC", "frage": "Für welche Zahl q hat x² + 5x + q = 0 genau eine Lösung?", "payload": {"kind": "short_input", "prompt": "Für welche Zahl q hat x² + 5x + q = 0 genau eine Lösung?"}, "params": {"p": 5}, "stufe": 5, "rolle": "generalprobe", "pm": {"1": {"ok": true}, "2": {"ok": true}, "3": {"ok": true}, "4": {"ok": true}, "5": {"ok": true}, "6": {"ok": true}, "7": {"ok": true}}, "afb": "II", "correct": ["25/4", "6,25", "6.25"], "acceptance": {"canonical": "25/4", "equivalents": ["6,25", "6.25"], "known_errors": {"5/2": "qf_halbes_p_nicht_quadriert", "2,5": "qf_halbes_p_nicht_quadriert", "2.5": "qf_halbes_p_nicht_quadriert", "-25/4": "qf_q_vorzeichen", "−25/4": "qf_q_vorzeichen", "-6,25": "qf_q_vorzeichen", "−6,25": "qf_q_vorzeichen", "-6.25": "qf_q_vorzeichen", "−6.25": "qf_q_vorzeichen"}}, "parts": null, "figur": null, "optionen": null, "solution": "Genau eine Lösung heißt: (p/2)² − q = 0.\n(5/2)² − q = 0\nq = (5/2)²\nq = 25/4", "hints": [{"level": 1, "text": "Wann hat eine quadratische Gleichung genau eine Lösung?", "status": "entwurf"}, {"level": 2, "text": "Der Ausdruck unter der Wurzel muss 0 sein: (p/2)² − q = 0.", "status": "entwurf"}, {"level": 3, "text": "Setz p = 5 ein und stell nach q um.", "status": "entwurf"}]}]'::jsonb)
             as v(suffix text, input_type text, frage text, payload jsonb, params jsonb, stufe int, rolle text,
                  pm jsonb, afb text, correct jsonb, acceptance jsonb, parts jsonb, figur jsonb, optionen jsonb,
                  solution text, hints jsonb)),
     neu as (
  insert into public.tasks (content_type, input_type, status, is_active, title, question, question_payload, parts, skill_key,
                            difficulty, afb, class_level, est_duration_sec, source, source_ref, einsatz, bauform_id,
                            bauform_version, params, stufe, rolle, kernidee_key, pruefmaschine)
  select 'exercise', v.input_type, 'draft', true, 'DI-3' || ' · ' || v.rolle || ' · S' || v.stufe, v.frage,
         v.payload, coalesce(v.parts, '[]'::jsonb), 'gleichung_quadr_anzahl', v.stufe, v.afb, 9, 120, 'bauform',
         'DI-3' || '-v' || b.version || '-' || v.suffix, '{session}', b.id, b.version, v.params, v.stufe,
         v.rolle, 'gleichung_quadr_anzahl:K1', v.pm
    from b, v
  on conflict (source, source_ref) do nothing
  returning id, source_ref),
     loes as (
  insert into public.task_solutions (task_id, correct_answers, acceptance, solution, hints)
  select neu.id, v.correct, v.acceptance, v.solution, v.hints
    from neu join b on true join v on neu.source_ref = 'DI-3' || '-v' || b.version || '-' || v.suffix
  returning task_id),
     fig as (
  -- Eine Figur je Aufgabe (task_figures) bzw. je Option einer Graph-Auswahl (task_figur_optionen); hochgeladen
  -- werden sie von scripts/figures/upload_figures.py (Rasit).
  insert into public.task_figures (task_id, generator, params, alt_text)
  select neu.id, v.figur ->> 'generator', v.figur -> 'params', v.figur ->> 'alt'
    from neu join b on true join v on neu.source_ref = 'DI-3' || '-v' || b.version || '-' || v.suffix
   where v.figur is not null
  returning task_id)
insert into public.task_figur_optionen (task_id, option_id, generator, params, alt_text)
select neu.id, o ->> 'option', o ->> 'generator', o -> 'params', o ->> 'alt'
  from neu join b on true join v on neu.source_ref = 'DI-3' || '-v' || b.version || '-' || v.suffix,
       jsonb_array_elements(coalesce(v.optionen, '[]')) o;
do $$ begin perform set_config('edvance.hinweis_status', '', true); perform set_config('edvance.bauform_export', '', true); end $$;
